const $=s=>document.querySelector(s), KEY='practice172.v1';
const defaultPlans=[{title:'上肢 A',kind:'力量',note:'引体向上与二头弯举 · 动作标准优先',ex:[['引体向上',4,'10–15','保留约2次余力，不追第一组极限'],['二头弯举',3,'10–15','肘部稳定，避免摆动']]},{title:'下肢 A',kind:'力量',note:'地面硬拉与提踵 · 按现有器械训练',ex:[['地面硬拉',3,'6–10','先确认动作和器械，重量按能力选择'],['提踵',2,'12–20','稳定支撑，缓慢下降']]},{title:'有氧与活动',kind:'有氧',note:'不负重快走30–40分钟 · 配合轻柔活动',ex:[]},{title:'上肢 B',kind:'力量',note:'引体向上与划船 · 给肩肘留出恢复空间',ex:[['引体向上',3,'8–12','比周一轻松，保留2–3次余力'],['划船',2,'10–15','器械固定可靠，避免腰部借力']]},{title:'下肢 B',kind:'力量',note:'地面硬拉轻量日 · 腰背疲劳时减量',ex:[['地面硬拉',3,'6–10','比周二轻松，避免做到力竭'],['山羊挺身',2,'10–15','可跳过；腰背疲劳时不与硬拉叠加']]},{title:'步行日',kind:'有氧',note:'不负重快走30–45分钟 · 可以分段完成',ex:[]},{title:'恢复日',kind:'恢复',note:'轻松散步或休息 · 检查睡眠和疲劳',ex:[]}];
let state;try{state=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}state=state||{profile:{height:172,weight:72,birth:1986,time:'19:00',reminder:'18:45',second:'20:00'},plans:structuredClone(defaultPlans),logs:[],checks:{},draft:null};
// Apply the confirmed equipment changes once; keep logs and in-progress sets intact.
if(state.planRevision!==2){
  state.plans.forEach((p,i)=>{
    p.ex=p.ex.flatMap(e=>{
      if(['俯卧撑','臀桥'].includes(e[0]))return [];
      if(e[0]==='深蹲 / 分腿蹲')return i===4?[structuredClone(defaultPlans[4].ex[0])]:[];
      if(e[0]==='地面硬拉 / 罗马尼亚硬拉')return [['地面硬拉',e[1],e[2],'先确认动作和器械，重量按能力选择']];
      if(e[0]==='二头弯举')return [ [e[0],3,e[2],e[3]] ];
      return [e];
    });
    if([0,1,3,4].includes(i))p.note=defaultPlans[i].note;
  });
  state.planRevision=2;
  try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}
}

let tab='today',day=(new Date().getDay()+6)%7,mode='normal',ends=0,timerHandle;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('保存失败：请先导出备份，检查设备存储空间');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
function stats(){const now=new Date(),start=new Date(now);start.setDate(now.getDate()-(now.getDay()+6)%7);start.setHours(0,0,0,0);const logs=state.logs.filter(l=>new Date(l.at)>=start);return {strength:logs.filter(l=>l.kind==='力量').length,minutes:logs.reduce((s,l)=>s+Number(l.walk||0),0),days:new Set(logs.map(l=>l.date)).size}}
function heading(k,title,sub){return `<div class="intro"><div><div class="eyebrow">${k}</div><h1>${title}</h1><div class="muted">${sub}</div></div><span class="pill">${esc(state.profile.height)} cm · ${esc(state.profile.weight)} kg</span></div>`}
function week(){return `<div class="week">${state.plans.map((p,i)=>`<button class="day ${i===day?'selected':''}" data-day="${i}"><small>周${'一二三四五六日'[i]}</small>${p.title.split(' ')[0].replace('有氧与活动','有氧').replace('恢复日','恢复').replace('步行日','步行')}<span class="daysub">${p.kind}</span></button>`).join('')}</div>`}
function checks(){const c=state.checks[dateKey()]||{};return `<div class="card"><h2>今天的小目标</h2>${[['walk','餐后轻松走10–15分钟','可计入当天步行'],['recover','留意睡眠与身体感受','疼痛时调整训练'],['food','吃好一餐，补足蛋白质','食物优先，补剂按需']].map(([id,t,s])=>`<label class="checkrow"><input type="checkbox" data-check="${id}" ${c[id]?'checked':''}><span>${t}<br><small>${s}</small></span></label>`).join('')}<div class="tip">每周安排力量、有氧与恢复。打卡记录行为，不用连续天数给自己施压。</div></div>`}
function today(){if(state.draft)return workout();const p=state.plans[day],s=stats();$('#view').innerHTML=heading('BUILD STRENGTH. KEEP BALANCE.','今天，练有所获','规律训练，让身体慢慢给出答案。')+week()+`<section class="hero"><div><div class="eyebrow">今日建议 / ${p.kind}</div><h2>${esc(p.title)}</h2><p>${esc(p.note)}</p><button id="start">${p.kind==='力量'?'开始今日训练':'记录今天的活动'}　↗</button></div><div class="orbit"><b>${p.kind==='力量'?'30–40':p.kind==='有氧'?'30+':'轻松'}</b><small>${p.kind==='恢复'?'恢复也算进步':'分钟 / 建议时长'}</small></div></section><div class="metrics"><div class="metric"><span>本周力量训练</span><b>${s.strength}<small> / 4</small></b><span>次已保存训练</span></div><div class="metric"><span>本周步行记录</span><b>${s.minutes}<small> 分钟</small></b><span>包含轻松与快走</span></div><div class="metric"><span>本周活动天数</span><b>${s.days}<small> 天</small></b><span>力量、步行或恢复</span></div></div><div class="two"><div class="card"><div class="section-top"><h2>训练清单</h2><button class="link" data-tab="plan">查看计划</button></div>${p.ex.length?p.ex.map((e,i)=>`<div class="exercise"><span class="number">0${i+1}</span><div class="desc"><h3>${esc(e[0])}</h3><small>${esc(e[3])}</small></div><span class="tag">${e[1]}组 × ${esc(e[2])}</span></div>`).join(''):`<p>${esc(p.note)}</p><div class="tip">步行可以分段进行。负重步行不作为默认任务，腿部疲劳时优先不负重。</div>`}<div class="tip">这是起始计划，重量需按器械和动作能力填写。腰、膝、肩、肘疼痛时先暂停相关动作。</div></div>${checks()}</div>`;$('#start').onclick=start}
function lastExercise(name){for(const l of state.logs){const e=l.ex.find(x=>x.name===name&&x.sets.some(s=>s.done));if(e)return e}return null}
function newSet(name,j){const prev=lastExercise(name)?.sets[j];return {kg:prev?.done?prev.kg:'0',reps:prev?.done?prev.reps:'',rir:prev?.done?prev.rir:'2',done:false}}
function choices(min,max,value,step=1){const values=[];for(let x=min;x<=max;x+=step)values.push(String(x));if(value!==''&&!values.includes(String(value)))values.push(String(value));values.sort((a,b)=>Number(a)-Number(b));return '<option value="">选择</option>'+values.map(x=>`<option value="${esc(x)}" ${String(value)===x?'selected':''}>${esc(x)}${Number(x)<min||Number(x)>max?'（原记录）':''}</option>`).join('')}
function field(e,s,i,j,k){const label={kg:'公斤',reps:'次数',rir:'余力'}[k];return `<select aria-label="${esc(e.name)}第${j+1}组${label}" data-i="${i}" data-j="${j}" data-field="${k}" ${s.done?'disabled':''}>${choices(k==='reps'?5:0,k==='kg'?100:k==='reps'?40:20,s[k],k==='kg'?.5:1)}</select>`}
function start(){let p=state.plans[day];state.draft={at:new Date().toISOString(),date:dateKey(),title:p.title,kind:p.kind,day,mode:'normal',ex:p.ex.map(e=>({name:e[0],note:e[3],range:e[2],sets:Array.from({length:Math.min(7,e[1])},(_,j)=>newSet(e[0],j))})),walk:'',minutes:35,feel:'正常',note:''};save();render()}
function workout(){const d=state.draft,done=d.ex.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0),total=d.ex.reduce((n,e)=>n+e.sets.length,0);$('#view').innerHTML=heading('YOUR TRAINING SESSION',esc(d.title),'选好数字，完成一组。按自己的节奏来。')+`<div class="session-progress"><div><b>${done}<small> / ${total} 组</small></b><span>今天的训练进度</span></div><div class="progress-track"><i style="width:${total?done/total*100:0}%"></i></div></div><div class="actions"><button id="reduce" class="secondary">${d.mode==='light'?'已减量':'今天减量'}</button><button id="recovery" class="secondary">改为恢复日</button><button id="manualTimer" class="secondary">休息 2分钟</button></div>${d.ex.map((e,i)=>`<section class="card workout-card" id="exercise-${i}"><div class="exercise-title"><span class="exercise-badge">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(e.name)}</h2><span class="muted">目标 ${esc(e.range)}次 · ${e.sets.filter(s=>s.done).length}/${e.sets.length}组完成</span></div><label class="group-picker">组数<select aria-label="${esc(e.name)}组数" data-groups="${i}">${Array.from({length:7},(_,j)=>`<option value="${j+1}" ${e.sets.length===j+1?'selected':''}>${j+1}组</option>`).join('')}</select></label></div><p>${esc(e.note)}</p><div class="last-hint">${lastExercise(e.name)?'↻ 已带出上次同组数据，完成前请核对':'○ 首次记录，选择这组的重量和次数'}<small>公斤为额外负重，徒手选0</small></div><div class="set-head"><span>组</span><span>公斤⌄</span><span>次数⌄</span><span>余力⌄</span><span></span></div>${e.sets.map((s,j)=>`<div id="set-${i}-${j}" class="setrow ${s.done?'done':e.sets.findIndex(x=>!x.done)===j?'current':''}"><span class="set-index">${s.done?'✓':j+1}</span>${['kg','reps','rir'].map(k=>field(e,s,i,j,k)).join('')}<button aria-label="${s.done?'撤销':'完成'}${esc(e.name)}第${j+1}组" data-done="${i},${j}">${s.done?'撤销':'完成'}</button></div>`).join('')}</section>`).join('')}<section class="card"><h2>收尾记录</h2><div class="form-grid"><label>本次总时长 / 分钟<input id="minutes" type="number" min="1" max="300" value="${esc(d.minutes)}"></label><label>今天步行 / 分钟<input id="walk" type="number" min="0" max="600" placeholder="0" value="${esc(d.walk)}"></label><label>身体感受<select id="feel">${['正常','轻松','疲劳','有疼痛'].map(x=>`<option ${d.feel===x?'selected':''}>${x}</option>`).join('')}</select></label><label>备注<input id="note" placeholder="今天的感受" value="${esc(d.note)}"></label></div><div class="actions"><button id="finish" class="primary">保存本次打卡 ✓</button><button id="discard" class="secondary">放弃本次草稿</button></div><small>未完成组如实保留；步行不要重复填写。</small></section>`;
document.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>{d.ex[el.dataset.i].sets[el.dataset.j][el.dataset.field]=el.value;save()});
document.querySelectorAll('[data-groups]').forEach(el=>el.onchange=()=>{const e=d.ex[el.dataset.groups],n=+el.value;if(n<e.sets.length&&e.sets.slice(n).some(s=>s.done||s.reps!=='')){if(!confirm('减少组数会移除末尾已填写的组，继续吗？')){el.value=e.sets.length;return}}while(e.sets.length<n)e.sets.push(newSet(e.name,e.sets.length));e.sets.length=n;save();render();$('#exercise-'+el.dataset.groups)?.scrollIntoView({block:'start',behavior:'smooth'})});
document.querySelectorAll('[data-done]').forEach(el=>el.onclick=()=>{const [i,j]=el.dataset.done.split(',').map(Number),s=d.ex[i].sets[j];if(!s.done&&(!valid(s.kg,0,100)||!valid(s.reps,5,40,true)||!valid(s.rir,0,20,true))){toast('请选择0–100公斤、5–40次，以及余力');return}const completing=!s.done;s.done=completing;save();if(completing)startTimer(120);render();if(completing){let next;for(let a=i;a<d.ex.length&&!next;a++){const b=d.ex[a].sets.findIndex(x=>!x.done);if(b>=0)next=$('#set-'+a+'-'+b)}next?.scrollIntoView({block:'center',behavior:'smooth'})}});
['minutes','walk','feel','note'].forEach(id=>$('#'+id).oninput=e=>{d[id]=e.target.value;save()});$('#manualTimer').onclick=()=>startTimer(120);$('#reduce').onclick=()=>{if(d.mode==='light'){toast('已经减量，可按感受跳过未完成组');return}d.mode='light';d.ex.forEach(e=>{const idx=e.sets.findLastIndex(s=>!s.done);if(idx>=0&&e.sets.length>1)e.sets.splice(idx,1)});save();render()};$('#recovery').onclick=()=>{if(!confirm('改为恢复日？本次已填写的力量组将移除。'))return;d.kind='恢复';d.title='恢复日';d.ex=[];save();render()};$('#discard').onclick=()=>{if(confirm('放弃尚未保存的本次记录？')){state.draft=null;save();stopTimer();render()}};$('#finish').onclick=()=>{if(!valid(d.minutes,1,300,true)||(d.walk!==''&&!valid(d.walk,0,600,true))){toast('请填写有效时长');return}if(d.kind==='力量'&&!d.ex.some(e=>e.sets.some(s=>s.done))){toast('请完成至少一组，或改为恢复日');return}state.logs.unshift({...structuredClone(d),id:crypto.randomUUID(),savedAt:new Date().toISOString()});state.draft=null;if(save()){stopTimer();tab='history';render();toast('本次记录已保存。今天又积累了一点。')}}}
function valid(x,min,max,int=false){return String(x).trim()!==''&&Number.isFinite(+x)&&+x>=min&&+x<=max&&(!int||Number.isInteger(+x))}
function plan(){const p=state.plans[day];$('#view').innerHTML=heading('YOUR WEEK, YOUR RHYTHM.','给这一周，留好节奏','四天力量、两天有氧、一天恢复，可按身体感受调整。')+week()+`<section class="card"><h2>周${'一二三四五六日'[day]} · ${esc(p.title)}</h2><p class="muted">${esc(p.note)}</p>${p.ex.map((e,i)=>`<div class="exercise"><span class="number">0${i+1}</span><div class="desc"><h3>${esc(e[0])}</h3><small>${esc(e[3])}</small></div><span class="tag">${e[1]}组 × ${esc(e[2])}</span></div>`).join('')}<div class="actions"><button id="trainPlan" class="primary">按此计划开始</button><button id="editPlan" class="secondary">编辑这一天</button></div><div id="editor"></div></section><div class="notice">进阶建议：连续两次能标准完成目标次数上限，再小幅增加重量或难度。硬拉与山羊挺身都有后侧负荷；疲劳明显时减量。同一部位的训练间隔只是起点，不能代替恢复判断。</div><div class="card sources"><h3>计划依据与使用范围</h3><p>起始安排适用于没有运动禁忌的成年人；当前器械、负重和伤痛情况尚未确认。请根据实际条件调整。血糖、血脂不由应用诊断，手环也不用于测量血糖。</p><a href="https://www.who.int/europe/publications/i/item/9789240014886" target="_blank" rel="noopener">WHO：有氧与力量活动建议 ↗</a><br><a href="https://www.diabetes.ca/living-with-diabetes/tools-and-resources/tips-to-help-prevent-blood-sugar-spikes-after-meals" target="_blank" rel="noopener">餐后轻松步行与血糖管理 ↗</a></div>`;$('#trainPlan').onclick=()=>{if(state.draft){tab='today';render();toast('请先完成或放弃当前草稿')}else{start();tab='today';render()}};$('#editPlan').onclick=()=>{$('#editor').innerHTML=`<div class="form-grid planedit"><label>名称<input id="pt" value="${esc(p.title)}"></label><label>类型<select id="pk">${['力量','有氧','恢复'].map(x=>`<option ${p.kind===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="wide">安排说明<input id="pn" value="${esc(p.note)}"></label><label class="wide">动作：每行 名称 | 组数 | 次数范围 | 提示<textarea id="pe" rows="7">${esc(p.ex.map(e=>e.join(' | ')).join('\n'))}</textarea></label></div><div class="actions"><button id="savePlan" class="primary">保存计划</button><button id="resetPlan" class="secondary">恢复这一天的初始计划</button></div>`;$('#savePlan').onclick=()=>{const lines=$('#pe').value.trim().split('\n').filter(x=>x.trim()),ex=lines.map(l=>l.split('|').map(x=>x.trim()));if(!$('#pt').value.trim()||ex.length>12||ex.some(e=>e.length!==4||!e[0]||!valid(e[1],1,7,true)||!e[2])){toast('每行请用 | 分隔四项，组数1–7，最多12个动作');return}if($('#pk').value==='力量'&&!ex.length){toast('力量日请至少添加一个动作');return}state.plans[day]={title:$('#pt').value.trim(),kind:$('#pk').value,note:$('#pn').value,ex:ex.map(e=>[e[0],+e[1],e[2],e[3]])};save();render();toast('计划已更新')};$('#resetPlan').onclick=()=>{if(confirm('恢复这一天的初始计划？')){state.plans[day]=structuredClone(defaultPlans[day]);save();render()}}}}
function history(){const s=stats();$('#view').innerHTML=heading('SMALL STEPS, REAL PROGRESS.','每一次，都算数','记录完成的训练，也记录身体需要放慢的时候。')+`<div class="metrics"><div class="metric"><span>累计活动记录</span><b>${state.logs.length}</b><span>次真实打卡</span></div><div class="metric"><span>本周力量训练</span><b>${s.strength}</b><span>次训练</span></div><div class="metric"><span>本周步行</span><b>${s.minutes}</b><span>分钟</span></div></div><section class="card"><div class="section-top"><h2>训练手记</h2><button id="exportLogs" class="link">导出全部备份</button></div>${state.logs.length?state.logs.map(l=>`<details class="history-item"><summary>${esc(l.date)}　${esc(l.title)} <small>· ${esc(l.minutes)}分钟 · ${esc(l.feel)}</small></summary>${l.ex.map(e=>`<p><b>${esc(e.name)}</b><br>${e.sets.map((s,j)=>`${j+1}组：${s.done?`${esc(s.kg)}kg × ${esc(s.reps)}次，余力${esc(s.rir)}`:'未完成'}`).join(' / ')}</p>`).join('')}<p>步行：${Number(l.walk||0)}分钟${l.note?' · '+esc(l.note):''}</p><button class="link" data-delete="${esc(l.id)}">删除这条记录</button></details>`).join(''):'<div class="empty"><div class="big">↗</div>第一条记录，从今天开始。<p>完成训练后，重量、次数和感受会显示在这里。</p></div>'}</section>`;$('#exportLogs').onclick=backup;document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('删除这条记录？此操作不能撤销。')){state.logs=state.logs.filter(l=>l.id!==b.dataset.delete);save();render()}})}
function backup(){download('练有所获-备份-'+dateKey()+'.json',JSON.stringify({format:KEY,state},null,2),'application/json')}
function settings(){$('#view').innerHTML=heading('MADE FOR YOUR DAILY LIFE.','按你的节奏来','个人资料、提醒与数据，都由你掌握。')+`<section class="card"><h2>个人设置</h2><form id="profile"><div class="form-grid"><label>身高 / cm<input name="height" type="number" min="100" max="230" required value="${esc(state.profile.height)}"></label><label>体重 / kg<input name="weight" type="number" min="30" max="250" step="0.1" required value="${esc(state.profile.weight)}"></label><label>出生年份<input name="birth" type="number" min="1920" max="2010" required value="${esc(state.profile.birth)}"></label><label>晚间训练时间<input name="time" type="time" required value="${esc(state.profile.time)}"></label><label>每天提醒一<input name="reminder" type="time" required value="${esc(state.profile.reminder)}"></label><label>每天提醒二<input name="second" type="time" required value="${esc(state.profile.second)}"></label></div><div class="actions"><button class="primary" type="submit">保存设置</button></div></form></section><section class="card" style="margin-top:20px"><h2>每天两次，温和提醒</h2><p class="muted">第一版通过日历提醒，不会在网页关闭后自行弹出通知。</p><div class="actions"><button id="calendar" class="primary">下载30天日历提醒</button><button id="testSound" class="secondary">测试组间提示音</button></div><div class="notice">下载后将 .ics 文件导入 iPhone 日历，允许日历通知。两次提醒分别为「按计划训练或恢复」及「补记今天的活动」。重复导入可能产生重复事件，修改时间后请先删除旧事件。</div><p class="sources">小米手环：先在小米运动健康与iPhone设置中允许通知，并保持蓝牙连接。请用一条手机日历通知实测锁屏与手环振动。此应用没有直接连接手环或自动同步健康数据。</p></section><section class="card" style="margin-top:20px"><h2>设备上的记录</h2><p class="muted">记录只存在当前浏览器。更换设备、清除网站数据或卸载后可能丢失，请定期备份。</p><div class="actions"><button id="backup">导出备份</button><button id="import">恢复备份</button><input id="file" type="file" accept=".json,application/json" hidden></div><div class="notice">iPhone使用：在Safari打开网站 → 分享 → 添加到主屏幕。离线使用需先在线打开一次；无需登录；记录仅保存在当前设备。</div></section>`;$('#profile').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);state.profile=Object.fromEntries(data);save();render();toast('设置已保存；提醒时间变更后请重新导入日历')};$('#calendar').onclick=calendar;$('#testSound').onclick=()=>{beep();toast('提示音已尝试播放；静音设置可能影响声音')};$('#backup').onclick=backup;$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const v=JSON.parse(await e.target.files[0].text());if(v.format!==KEY||!v.state||!Array.isArray(v.state.logs)||!Array.isArray(v.state.plans)||v.state.plans.length!==7||!v.state.profile||!v.state.checks)throw Error();if(!v.state.plans.every(p=>typeof p.title==='string'&&['力量','有氧','恢复'].includes(p.kind)&&Array.isArray(p.ex)&&p.ex.every(x=>Array.isArray(x)&&x.length===4&&valid(x[1],1,8,true))))throw Error();if(!v.state.logs.every(l=>Array.isArray(l.ex)&&l.ex.every(x=>Array.isArray(x.sets))))throw Error();if(confirm('用备份替换当前设备的全部记录？建议先导出当前备份。')){state=v.state;state.draft=null;save();render();toast('备份已恢复')}}catch{toast('无法读取备份，请选择本应用导出的有效JSON文件')}}}
function calendar(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Practice172//Training//ZH','CALSCALE:GREGORIAN'];for(let i=0;i<30;i++){const d=new Date();d.setDate(d.getDate()+i);for(const [n,time,title] of [[1,state.profile.reminder,'练有所获：按计划训练或恢复'],[2,state.profile.second,'练有所获：补记今天的活动']]){const [h,m]=time.split(':').map(Number);d.setHours(h,m,0,0);if(d<=new Date())continue;const utc=x=>x.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');lines.push('BEGIN:VEVENT','UID:'+dateKey(d)+'-'+n+'-practice172@local','DTSTAMP:'+utc(new Date()),'DTSTART:'+utc(d),'DTEND:'+utc(new Date(+d+5*60000)),'SUMMARY:'+title,'DESCRIPTION:打开练有所获，按身体感受训练或休息。','BEGIN:VALARM','TRIGGER:PT0S','ACTION:DISPLAY','DESCRIPTION:'+title,'END:VALARM','END:VEVENT')}}lines.push('END:VCALENDAR');download('练有所获-30天提醒.ics',lines.join('\r\n')+'\r\n','text/calendar;charset=utf-8');toast('日历已生成；使用当前设备时区，请导入后测试提醒')}
let audioCtx;function beep(){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=660;g.gain.value=.12;o.start();o.stop(audioCtx.currentTime+.35)}catch{}}
function startTimer(seconds){ends=Date.now()+seconds*1000;$('#timer').hidden=false;clearInterval(timerHandle);tick();timerHandle=setInterval(tick,250);try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume()}catch{}}
function tick(){const n=Math.max(0,Math.ceil((ends-Date.now())/1000));$('#countdown').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(!n){stopTimer();beep();toast('休息结束。准备好再开始下一组。')}}function stopTimer(){clearInterval(timerHandle);ends=0;$('#timer').hidden=true}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));({today,plan,history,settings}[tab])();}
document.addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;render();window.scrollTo(0,0)}const d=e.target.closest('[data-day]');if(d){day=+d.dataset.day;render()}});document.addEventListener('change',e=>{if(e.target.dataset.check){state.checks[dateKey()]||={};state.checks[dateKey()][e.target.dataset.check]=e.target.checked;save()}});$('#addTime').onclick=()=>{ends+=30000;tick()};$('#stopTimer').onclick=stopTimer;$('#date').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
